/**
 * Tiny synthetic images for the provider probes, built from bytes so the probes
 * never read a file from disk.
 */

import { crc32, deflateSync } from "node:zlib";

function pngChunk(type, data) {
  const typeBytes = Buffer.from(type, "ascii");
  const length = Buffer.alloc(4);
  length.writeUInt32BE(data.length);
  const checksum = Buffer.alloc(4);
  checksum.writeUInt32BE(crc32(Buffer.concat([typeBytes, data])));
  return Buffer.concat([length, typeBytes, data, checksum]);
}

/** A 2x2 PNG whose pixels are all pure red (8-bit RGB, no alpha). */
export function buildRedPng() {
  const signature = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);
  const header = Buffer.alloc(13);
  header.writeUInt32BE(2, 0); // width
  header.writeUInt32BE(2, 4); // height
  header[8] = 8; // bit depth
  header[9] = 2; // colour type: truecolour (RGB)
  // Bytes 10 to 12 stay zero: deflate compression, adaptive filtering, no interlace.

  const redPixel = [0xff, 0x00, 0x00];
  // Each scanline starts with a filter-type byte (0 means "none").
  const scanline = [0, ...redPixel, ...redPixel];
  const pixels = Buffer.from([...scanline, ...scanline]);

  return Buffer.concat([
    signature,
    pngChunk("IHDR", header),
    pngChunk("IDAT", deflateSync(pixels)),
    pngChunk("IEND", Buffer.alloc(0)),
  ]);
}

/**
 * A 2x2 red JPEG (776 bytes), embedded as base64 because assembling JPEG
 * Huffman tables by hand adds nothing to a probe. It was made once by converting
 * the PNG above with macOS `sips` (quality 70). An earlier hand-trimmed 134-byte
 * JPEG decoded in `sips`, but SubQ rejected it as truncated, so keep this one.
 */
export function buildRedJpeg() {
  return Buffer.from(
    "",
    "base64",
  );
}
